package vn.edu.eaut.lab6.filter; import jakarta.servlet.*;import jakarta.servlet.annotation.WebFilter;import jakarta.servlet.http.*;import java.io.*;@WebFilter("/*") public class AccessLogFilter implements Filter{public void doFilter(ServletRequest a,ServletResponse b,FilterChain c)throws IOException,ServletException{long st=System.currentTimeMillis();HttpServletRequest q=(HttpServletRequest)a;HttpSession s=q.getSession(false);String u=s==null?"anonymous":String.valueOf(s.getAttribute("username"));try{c.doFilter(a,b);}finally{System.out.println("[ACCESS] "+q.getMethod()+" "+q.getRequestURI()+" | user="+u+" | "+(System.currentTimeMillis()-st)+"ms");}}}
